import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as l,o as e,af as o}from"./chunks/mermaid.DrCHRkU0.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const m=JSON.parse('{"title":"Common Workflow Patterns for AI Agents","description":"","frontmatter":{},"headers":[],"relativePath":"zh/tech/agent/common-workflow-patterns-ai-agents.md","filePath":"zh/tech/agent/common-workflow-patterns-ai-agents.md","lastUpdated":1780929478000}'),r={name:"zh/tech/agent/common-workflow-patterns-ai-agents.md"};function i(n,a,h,s,d,u){return e(),l("div",null,[...a[0]||(a[0]=[o('<h1 id="common-workflow-patterns-for-ai-agents" tabindex="-1">Common Workflow Patterns for AI Agents <a class="header-anchor" href="#common-workflow-patterns-for-ai-agents" aria-label="Permalink to &quot;Common Workflow Patterns for AI Agents&quot;">​</a></h1><blockquote><p>原文: <a href="https://claude.com/blog/common-workflow-patterns-for-ai-agents-and-when-to-use-them" target="_blank" rel="noreferrer">https://claude.com/blog/common-workflow-patterns-for-ai-agents-and-when-to-use-them</a></p></blockquote><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>AI agents 自主做出决策，而工作流（Workflows）则为这种自主性引入结构。工作流建立了执行模式，将 agent 的能力引导向需要协调步骤、可预测结果和编排时机的复杂问题。</p><p>当多个 agents 需要协同工作时，真正的决策在于选择哪种模式来适配你的问题。</p><p>在生产环境中，三种模式覆盖了绝大多数用例：<strong>顺序执行</strong>、<strong>并行执行</strong>和<strong>评估优化器</strong>。</p><h2 id="工作流-vs-自主-agent" tabindex="-1">工作流 vs 自主 Agent <a class="header-anchor" href="#工作流-vs-自主-agent" aria-label="Permalink to &quot;工作流 vs 自主 Agent&quot;">​</a></h2><p>工作流不取代 agent 的自主性，而是塑造 agent 自主性的应用方式和位置。</p><ul><li><strong>完全自主的 agent</strong>: 自己决定使用什么工具、以什么顺序执行任务、何时停止</li><li><strong>工作流</strong>: 建立总体流程、定义检查点、设置边界，agent 在这些边界内仍有动态行为</li></ul><p>每个工作流步骤仍然可以利用 agent 的推理和工具使用能力，但整体编排遵循预定义的路径。</p><h2 id="三种核心工作流模式" tabindex="-1">三种核心工作流模式 <a class="header-anchor" href="#三种核心工作流模式" aria-label="Permalink to &quot;三种核心工作流模式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模式</th><th>解决的问题</th><th>何时使用</th><th>权衡</th><th>收益</th></tr></thead><tbody><tr><td><strong>Sequential</strong></td><td>任务有依赖：步骤 B 需要步骤 A 的输出</td><td>多阶段流程、数据管道、draft-review-polish 循环</td><td>增加延迟（每步等待上一步）</td><td>通过让每个 agent 专注一件事来提高准确性</td></tr><tr><td><strong>Parallel</strong></td><td>任务独立，逐个处理太慢</td><td>多维度评估、代码审查、文档分析</td><td>成本更高（多个并发 API 调用）需要聚合策略</td><td>更快完成，跨工程团队分离关注点</td></tr><tr><td><strong>Evaluator-optimizer</strong></td><td>第一次输出质量不够好</td><td>技术文档、客户沟通、针对特定标准的代码生成</td><td>倍增 token 使用和迭代时间</td><td>通过结构化反馈循环生成更好的输出</td></tr></tbody></table><blockquote><p><strong>核心建议</strong>: 从最简单的能解决问题的模式开始。默认选择顺序执行。当延迟是瓶颈且任务独立时转向并行。只有当能衡量质量提升时，才添加 evaluator-optimizer 循环。</p></blockquote><h2 id="_1-顺序工作流-sequential-workflows" tabindex="-1">1. 顺序工作流（Sequential Workflows） <a class="header-anchor" href="#_1-顺序工作流-sequential-workflows" aria-label="Permalink to &quot;1. 顺序工作流（Sequential Workflows）&quot;">​</a></h2><p>顺序工作流按预定顺序执行任务。</p><p>每个阶段的 agent 处理输入、做出决策、必要时调用工具，然后将结果传递给下一阶段。输出线性流经系统，形成清晰的操作链。</p><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>多阶段流程，每步依赖前一步输出</li><li>数据转换管道，每阶段增加特定价值</li><li>因固有依赖无法并行化的任务</li><li>draft-review-polish 循环</li></ul><h3 id="何时避免" tabindex="-1">何时避免 <a class="header-anchor" href="#何时避免" aria-label="Permalink to &quot;何时避免&quot;">​</a></h3><ul><li>单个 agent 能有效处理整个任务时</li><li>agents 需要协作而非顺序交接时</li></ul><h3 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h3><ul><li>生成营销文案 → 翻译成多种语言</li><li>从文档提取数据 → 针对 schema 验证 → 加载到数据库</li><li>内容审核管道：提取内容 → 分类 → 应用审核规则 → 路由</li></ul><h3 id="技巧" tabindex="-1">技巧 <a class="header-anchor" href="#技巧" aria-label="Permalink to &quot;技巧&quot;">​</a></h3><p>先尝试作为单个 agent 运行 pipeline，步骤只是 prompt 的一部分。如果这样就够了，就无需额外复杂性。</p><h2 id="_2-并行工作流-parallel-workflows" tabindex="-1">2. 并行工作流（Parallel Workflows） <a class="header-anchor" href="#_2-并行工作流-parallel-workflows" aria-label="Permalink to &quot;2. 并行工作流（Parallel Workflows）&quot;">​</a></h2><p>并行工作流将独立任务分配给多个 agents 同时执行。</p><p>不等一个 agent 完成就启动下一个，多个 agents 同时运行，然后合并结果。这种模式在任务不依赖彼此时能显著提升速度。</p><p>类似于分布式系统中的 fan-out/fan-in 模式。</p><h3 id="何时使用-1" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用-1" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>任务可分解为独立子任务且同时处理有益时</li><li>需要多个视角审视同一问题时</li><li>不同工程师独立拥有和优化各自的 agents 时</li><li>复杂任务中，用独立 AI 调用处理每个考虑因素通常优于在一个调用中同时处理所有</li></ul><h3 id="何时避免-1" tabindex="-1">何时避免 <a class="header-anchor" href="#何时避免-1" aria-label="Permalink to &quot;何时避免&quot;">​</a></h3><ul><li>agents 需要累积上下文或必须互相构建时</li><li>API 配额等资源限制使并发处理不切实际时</li><li>缺乏清晰策略处理不同 agents 的矛盾结果时</li><li>结果聚合过于复杂或降级输出质量时</li></ul><h3 id="示例-1" tabindex="-1">示例 <a class="header-anchor" href="#示例-1" aria-label="Permalink to &quot;示例&quot;">​</a></h3><ul><li>自动化评估：每个 agent 检查不同质量指标</li><li>代码审查：多个 agents 检查不同漏洞类别</li><li>文档分析：并行提取主题、情感分析和事实核查</li></ul><h3 id="技巧-1" tabindex="-1">技巧 <a class="header-anchor" href="#技巧-1" aria-label="Permalink to &quot;技巧&quot;">​</a></h3><p>在实现并行 agents 前先设计聚合策略。是取多数票？平均置信度分数？还是听从最专业的 agent？</p><h2 id="_3-评估优化器工作流-evaluator-optimizer-workflows" tabindex="-1">3. 评估优化器工作流（Evaluator-Optimizer Workflows） <a class="header-anchor" href="#_3-评估优化器工作流-evaluator-optimizer-workflows" aria-label="Permalink to &quot;3. 评估优化器工作流（Evaluator-Optimizer Workflows）&quot;">​</a></h2><p>评估优化器工作流将两个 agents 配对形成迭代循环：</p><ol><li>一个生成内容</li><li>另一个根据标准评估</li><li>生成器根据反馈改进</li><li>循环直到输出达到质量阈值或最大迭代次数</li></ol><p>核心洞察：生成和评估是不同认知任务。分离它们让每个 agent 专业化——生成器专注产出内容，评估器专注应用一致的质量标准。</p><h3 id="何时使用-2" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用-2" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>有清晰、可衡量的质量标准，AI 评估器能一致应用时</li><li>首次尝试和最终质量之间的差距足够大，值得额外 token 和延迟投入时</li></ul><h3 id="何时避免-2" tabindex="-1">何时避免 <a class="header-anchor" href="#何时避免-2" aria-label="Permalink to &quot;何时避免&quot;">​</a></h3><ul><li>首次尝试质量已满足需求时</li><li>实时应用需要即时响应时</li><li>简单分类等日常任务时</li><li>评估标准对 AI 评估器来说过于主观时</li><li>存在确定性工具（如代码风格的 linter）时</li></ul><h3 id="示例-2" tabindex="-1">示例 <a class="header-anchor" href="#示例-2" aria-label="Permalink to &quot;示例&quot;">​</a></h3><ul><li>API 文档生成（生成器写文档，评估器对照代码库检查完整性、清晰度和准确性）</li><li>客户沟通（生成器起草邮件，评估器评估语调和策略合规性）</li><li>SQL 查询生成（生成器写查询，评估器检查效率和安全性问题）</li></ul><h3 id="技巧-2" tabindex="-1">技巧 <a class="header-anchor" href="#技巧-2" aria-label="Permalink to &quot;技巧&quot;">​</a></h3><p>在开始迭代前设置清晰的停止标准。定义最大迭代次数和具体质量阈值。没有这些护栏，你可能陷入昂贵循环——评估器不断发现小问题，生成器不断调整，但质量早已 plateau。</p><h2 id="选择合适的工作流模式" tabindex="-1">选择合适的工作流模式 <a class="header-anchor" href="#选择合适的工作流模式" aria-label="Permalink to &quot;选择合适的工作流模式&quot;">​</a></h2><p>选择正确的模式取决于任务结构、质量要求和资源约束。</p><h3 id="决策问题" tabindex="-1">决策问题 <a class="header-anchor" href="#决策问题" aria-label="Permalink to &quot;决策问题&quot;">​</a></h3><ol><li>单个 agent 能有效处理这个任务吗？ → 如果是，根本不需要工作流</li><li>任务有清晰顺序依赖吗？ → 使用顺序工作流</li><li>子任务能独立同时处理，且更快完成有帮助吗？ → 考虑并行工作流</li><li>迭代改进能显著提升质量吗？ → 考虑评估优化器模式</li></ol><h3 id="还需要考虑" tabindex="-1">还需要考虑 <a class="header-anchor" href="#还需要考虑" aria-label="Permalink to &quot;还需要考虑&quot;">​</a></h3><ul><li><strong>故障处理</strong>: 为每步定义 fallback 行为和重试逻辑</li><li><strong>延迟和成本约束</strong>: 决定你能运行多少 agents、负担多少次迭代</li><li><strong>衡量改进</strong>: 用单个 agent 设置基线，这样能判断工作流是否真正有帮助</li></ul><h2 id="组合模式" tabindex="-1">组合模式 <a class="header-anchor" href="#组合模式" aria-label="Permalink to &quot;组合模式&quot;">​</a></h2><p>这三种模式并非互斥。复杂性需求出现时可以嵌套它们：</p><ul><li>评估优化器工作流可以在评估阶段采用并行处理——多个评估器同时评估不同质量维度</li><li>顺序工作流可以在某些阶段包含并行处理——在进入下一步之前多个独立操作同时发生</li></ul><p>关键是将模式复杂度与实际需求匹配。不要因为能做到就添加并行处理——只有并发执行提供明确好处时才加。</p><h2 id="进阶建议" tabindex="-1">进阶建议 <a class="header-anchor" href="#进阶建议" aria-label="Permalink to &quot;进阶建议&quot;">​</a></h2><p>从能工作的最简单模式开始。如果顺序工作流能处理你的用例，不要添加并行化。如果首次质量够好，跳过评估优化器循环。</p><p>这三种模式提供了清晰升级路径：</p><ul><li>顺序工作流可以在瓶颈阶段加入并行处理</li><li>Agent 方法可以在质量标准收紧时添加评估</li><li>因为这些模式是模块化的，不需要完全重写</li></ul>',62)])])}const b=t(r,[["render",i]]);export{m as __pageData,b as default};
